import fs from 'node:fs'
import path from 'node:path'
import {fileURLToPath} from 'node:url'
import glob from 'fast-glob'
import {toId, storyNameFromExport} from 'storybook/internal/csf'
import ts from 'typescript'

const packageDirectory = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')

/** Region props are generated by the `RegionProps<Names>` mapped type, so their description is canonical. */
function regionDescription(component, region) {
  return `Supplies the ${region} region. Takes precedence over a matching \`${component}.${region[0].toUpperCase()}${region.slice(1)}\` child.`
}

function jsDocText(member) {
  const parts = []
  for (const doc of ts.getJSDocCommentsAndTags(member)) {
    const comment = doc.comment
    if (typeof comment === 'string') parts.push(comment)
    else if (Array.isArray(comment)) parts.push(comment.map(entry => entry.text ?? '').join(''))
  }
  return parts.join('\n').trim() || undefined
}

function readRegionNames(node) {
  const names = []
  for (const clause of node.heritageClauses ?? []) {
    for (const type of clause.types) {
      if (type.expression.getText() !== 'RegionProps') continue
      for (const argument of type.typeArguments ?? []) {
        for (const literal of argument.types ?? [argument]) {
          if (ts.isLiteralTypeNode(literal) && ts.isStringLiteral(literal.literal)) names.push(literal.literal.text)
        }
      }
    }
  }
  return names
}

/** Default values are declared in the component's destructuring, not in its props type. */
function readDefaults(source) {
  const defaults = new Map()
  const visit = node => {
    if (ts.isObjectBindingPattern(node)) {
      for (const element of node.elements) {
        if (!element.initializer || !ts.isIdentifier(element.name)) continue
        const key = (element.propertyName ?? element.name).getText().replace(/['"]/g, '')
        if (!defaults.has(key)) defaults.set(key, element.initializer.getText())
      }
    }
    ts.forEachChild(node, visit)
  }
  visit(source)
  return defaults
}

function normalizeType(node) {
  return node
    .getText()
    .replace(/\s*\n\s*/g, ' ')
    .replace(/\s{2,}/g, ' ')
    .trim()
}

function readPropsTypes(filePath, componentName) {
  const text = fs.readFileSync(filePath, 'utf8')
  const source = ts.createSourceFile(filePath, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TSX)
  const defaults = readDefaults(source)
  const types = new Map()

  const addMembers = (typeName, members, regions) => {
    const props = []
    for (const region of regions) {
      props.push({name: region, type: 'React.ReactNode', description: regionDescription(componentName, region)})
    }
    for (const member of members) {
      if (!ts.isPropertySignature(member) || !member.name) continue
      const name = member.name.getText().replace(/['"]/g, '')
      const prop = {name, type: member.type ? normalizeType(member.type) : 'unknown'}
      const defaultValue = defaults.get(name)
      if (defaultValue !== undefined) prop.defaultValue = defaultValue
      const description = jsDocText(member)
      if (description) prop.description = description
      props.push(prop)
    }
    if (props.length > 0)
      types.set(
        typeName,
        props.sort((a, b) => a.name.localeCompare(b.name)),
      )
  }

  const visit = node => {
    const isExported = node.modifiers?.some(modifier => modifier.kind === ts.SyntaxKind.ExportKeyword)
    if (isExported && ts.isInterfaceDeclaration(node) && node.name.text.endsWith('Props')) {
      addMembers(node.name.text, node.members, readRegionNames(node))
    }
    if (isExported && ts.isTypeAliasDeclaration(node) && node.name.text.endsWith('Props')) {
      const members = ts.isTypeLiteralNode(node.type)
        ? node.type.members
        : ts.isIntersectionTypeNode(node.type)
          ? node.type.types.flatMap(part => (ts.isTypeLiteralNode(part) ? part.members : []))
          : []
      addMembers(node.name.text, members, [])
    }
    ts.forEachChild(node, visit)
  }

  visit(source)
  return types
}

/** Story ids are derived with Storybook's own `toId`, so they cannot drift from what it registers. */
function readStoryIds(directory) {
  const ids = []
  for (const file of glob.sync('*.stories.tsx', {cwd: directory, absolute: true}).sort()) {
    const text = fs.readFileSync(file, 'utf8')
    const title = /title:\s*'([^']+)'/.exec(text)?.[1]
    if (!title) continue
    for (const match of text.matchAll(/^export const (\w+)\s*[:=]/gm)) {
      if (match[1] === 'default') continue
      ids.push({id: toId(title, storyNameFromExport(match[1]))})
    }
  }
  return ids.length > 0 ? ids : undefined
}

export function buildDocs(componentName) {
  const directory = path.join(packageDirectory, 'src/components', componentName)
  const sources = glob
    .sync('*.{ts,tsx}', {cwd: directory, absolute: true})
    .filter(file => !/\.(test|stories|storyHelpers)\./.test(file) && !file.endsWith('index.ts'))
    .sort()

  const types = new Map()
  for (const file of sources) {
    for (const [name, props] of readPropsTypes(file, componentName)) {
      if (!types.has(name)) types.set(name, props)
    }
  }

  const readme = path.join(directory, 'README.mdx')
  const intent = fs.existsSync(readme)
    ? new RegExp(`^# ${componentName}\\n\\n(.+?)\\n`, 'ms').exec(fs.readFileSync(readme, 'utf8'))?.[1].trim()
    : undefined

  const rootType = types.get(`${componentName}Props`) ?? types.get(`${componentName}RootProps`)

  const docs = {
    id: componentName.toLowerCase(),
    name: componentName,
    status: 'alpha',
    importPath: `@primer/react-tailwind/${componentName}`,
  }
  if (intent) docs.description = intent
  const stories = readStoryIds(directory)
  if (stories) docs.stories = stories
  if (rootType) docs.props = rootType

  const subcomponents = [...types.entries()]
    .filter(([name]) => name !== `${componentName}Props` && name !== `${componentName}RootProps`)
    .map(([name, props]) => ({name: name.replace(/Props$/, ''), props}))
  if (subcomponents.length > 0) docs.subcomponents = subcomponents

  return docs
}

if (import.meta.filename === process.argv[1]) {
  const only = process.argv.slice(2).filter(argument => !argument.startsWith('--'))
  const components = glob
    .sync('src/components/*/README.mdx', {cwd: packageDirectory})
    .map(file => path.basename(path.dirname(file)))
    .filter(name => only.length === 0 || only.includes(name))
    .sort()

  let written = 0
  for (const name of components) {
    const docs = buildDocs(name)
    const target = path.join(packageDirectory, 'src/components', name, `${name}.docs.json`)
    fs.writeFileSync(target, `${JSON.stringify(docs, null, 2)}\n`)
    written += 1
  }

  // eslint-disable-next-line no-console
  console.log(`Generated docs.json for ${written} component(s).`)
}
